    public static Object loadClosureClass(BAlongTree t, String stem, RTTI[] params) {
        //compute hashed key from RTTIs
        long hash = 0;
        for(int i = 0; i < params.length; i++) {
            hash = hash + params[i].getSN()*MagicNumbers.a(i);
        }

        //look in tree
        Object o = t.get(hash);
        if (o != null) 
